package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.List;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import org.jsoup.Jsoup;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.TextNode;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.*;
import org.jsoup.select.Elements;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class Element_html_TriageGen2Test {

    private Element element;

    @Before
    public void setUp() {
        element = new Element(Tag.valueOf("div"), "", new org.jsoup.nodes.Attributes());
    }

    @Test
    public void testEmptyElementHtml() {
        assertEquals("", element.html());
    }

    @Test
    public void testTextOnlyElementHtml() {
        element.appendChild(new TextNode("Hello World"));
        assertEquals("Hello World", element.html());
    }

    @Test
    public void testNestedElementHtml() {
        Element child = new Element(Tag.valueOf("span"), "", new org.jsoup.nodes.Attributes());
        child.appendChild(new TextNode("Nested Text"));
        element.appendChild(child);
        assertEquals("<span>Nested Text</span>", element.html());
    }

    @Test
    public void testNestedElementsWithTextHtml() {
        Element child1 = new Element(Tag.valueOf("span"), "", new org.jsoup.nodes.Attributes());
        child1.appendChild(new TextNode("First"));
        Element child2 = new Element(Tag.valueOf("span"), "", new org.jsoup.nodes.Attributes());
        child2.appendChild(new TextNode("Second"));
        element.appendChild(child1);
        element.appendChild(child2);
        assertEquals("<span>First</span><span>Second</span>", element.html());
    }

    @Test
    public void testElementWithAttributesHtml() {
        element.attr("id", "test");
        element.attr("class", "container");
        assertEquals("<div id=\"test\" class=\"container\"></div>", element.html());
    }

    @Test
    public void testComplexStructureHtml() {
        Element child1 = new Element(Tag.valueOf("span"), "", new org.jsoup.nodes.Attributes());
        child1.attr("class", "highlight");
        child1.appendChild(new TextNode("Highlighted Text"));

        Element child2 = new Element(Tag.valueOf("p"), "", new org.jsoup.nodes.Attributes());
        child2.appendChild(new TextNode("Paragraph Text"));

        element.appendChild(child1);
        element.appendChild(child2);

        String expectedHtml = "<span class=\"highlight\">Highlighted Text</span><p>Paragraph Text</p>";
        assertEquals(expectedHtml, element.html());
    }

    @Test
    public void testEmptyMethodHtml() {
        element.empty();
        assertEquals("", element.html());
    }

    @Test
    public void testAppendHtml() {
        element.append("<b>Bold Text</b>");
        assertEquals("<b>Bold Text</b>", element.html());
    }

    @Test
    public void testPrependHtml() {
        element.prepend("<i>Italic Text</i>");
        assertEquals("<i>Italic Text</i>", element.html());
    }

    @Test
    public void testReplaceAllHtml() {
        element.append("<b>Old Text</b>");
        element.html("<i>New Text</i>");
        assertEquals("<i>New Text</i>", element.html());
    }

    @Test
    public void testSelectAndHtml() {
        element.append("<div class=\"test\">Content</div>");
        Elements selected = element.getElementsByClass("test");
        assertTrue(selected.size() == 1);
        assertEquals("<div class=\"test\">Content</div>", selected.html());
    }
}
